package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;

/** Actual committed N06 originals + complete actual base. No current producer lease,
 * model-owned input, candidate PASS promotion or implicit initial-save permission. */
public final class DocumentCandidateAdoptionAuthority {
    private final JdbcTemplate db;private final DocumentReadService documents;private final ResourceReadAuthority resources;
    private final String schemaHash;private final TaskCandidateAssemblyStageJournal stages;private final TaskSourceVerifierSchema json=new TaskSourceVerifierSchema();
    public DocumentCandidateAdoptionAuthority(DataSource data,DocumentReadService documents,ResourceReadAuthority resources,TaskCandidateAssemblyStageJournal stages)throws Exception{try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/document-candidate-adoption.schema.json"))){schemaHash=WireValues.sha256(in.readAllBytes());}db=new JdbcTemplate(data);db.setQueryTimeout(5);this.documents=documents;this.resources=resources;this.stages=stages;}
    Verified require(EnterpriseAccess.Admission a,TaskCandidateAssemblyStageJournal.Original original,
            TaskCandidateAssemblyOriginalReader.Verified physical,DocumentReadService.FixedRead base)throws Exception {return require(a,original,physical,base,true);}
    Verified requireRead(EnterpriseAccess.Admission a,TaskCandidateAssemblyStageJournal.Original original,TaskCandidateAssemblyOriginalReader.Verified physical,DocumentReadService.FixedRead base)throws Exception{return require(a,original,physical,base,false);}
    private Verified require(EnterpriseAccess.Admission a,TaskCandidateAssemblyStageJournal.Original original,TaskCandidateAssemblyOriginalReader.Verified physical,DocumentReadService.FixedRead base,boolean editable)throws Exception {
        original.requireUnchanged();physical.requireUnchanged();documents.requireCurrent(a,base);
        stages.recovered(original,physical);
        var commit=stages.committed(original).orElseThrow(()->new TenantAccessException(ErrorCode.STEP_NOT_READY));
        if(!commit.produced().ready()||!physical.ready()||!physical.blockers().isEmpty())stale();
        String candidate=UUID.nameUUIDFromBytes(("N06_AGGREGATE/"+original.tenantId()+"/"+original.runId()).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();
        var input=original.input();same(base.bodySchemaRef(),physical.bodySchemaRef());same(base.bodySchemaSha256(),physical.bodySchemaSha256());var h=base.header();same(h.documentId(),text(input,"document_id"));same(h.documentRevision(),text(input,"base_document_revision"));same(h.bodySchemaRevision(),text(input,"body_schema_revision"));same(h.bodySha256(),text(input,"baseline_sha256"));same(h.planRevision(),text(input,"plan_revision"));same(h.snapshotId(),text(input,"snapshot_id"));same(h.taskId(),original.taskId());
        permissions(a,h,null,editable);var body=physical.artifact("DOCUMENT_BODY");var rows=db.queryForList("SELECT * FROM candidate WHERE tenant_id=? AND project_id=? AND candidate_id=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),candidate);
        if(rows.isEmpty()&&!editable)stale();if(rows.isEmpty())materialize(a,original,physical,base,candidate);
        var proof=new Verified(original,physical,base,candidate,editable);proof.requireCurrent(a);proof.baseline=proof.inspect(a);return proof;
    }
    private void materialize(EnterpriseAccess.Admission a,TaskCandidateAssemblyStageJournal.Original original,TaskCandidateAssemblyOriginalReader.Verified physical,DocumentReadService.FixedRead base,String id)throws Exception {
        var h=base.header();var body=physical.artifact("DOCUMENT_BODY");var at=now();var manifest=body.receipt().required("dependency_manifest");
        var evidence=one(db.queryForList("SELECT a.artifact_id FROM artifact a JOIN artifact_content_binding b ON b.tenant_id=a.tenant_id AND b.artifact_id=a.artifact_id WHERE a.tenant_id=? AND a.project_id=? AND a.document_revision=? AND a.artifact_kind='DOCUMENT_EVIDENCE' AND b.resource_kind='DOCUMENT' AND b.resource_id=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision(),h.documentId()));
        var binding=one(db.queryForList("SELECT lease_generation FROM step_action_binding WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND action_id=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),original.runId(),original.stepId(),original.actionId()));
        insert("version_registry",Map.of("tenant_id",h.tenantId(),"owner_project_id",h.projectId(),"version_id",id,"entity_kind","CANDIDATE","content_sha256",body.reference().sha256()));
        var row=meta(a,h,at);row.putAll(Map.of("candidate_id",id,"candidate_kind","DOCUMENT","task_id",h.taskId(),"task_revision",h.taskRevision(),"template_version",h.templateVersion(),"run_id",original.runId(),"step_id",original.stepId(),"action_id",original.actionId(),"lease_generation",binding.get("lease_generation")));
        row.putAll(Map.of("base_document_revision",h.documentRevision(),"input_sha256",original.inputSha256(),"snapshot_id",h.snapshotId(),"plan_revision",h.planRevision(),"target_sections",json.canonical(original.input().required("assigned_section_ids")),"target_node_ids",json.canonical(original.input().required("requirement_node_ids")),"content_ref",StoredObjectReferences.encode(body.reference()),"content_artifact_id",body.artifactId(),"evidence_refs",json.canonical(physical.manifest().required("evidence_refs"))));
        row.putAll(Map.of("original_evidence_artifact_id",str(evidence,"artifact_id"),"new_evidence_artifact_id",body.artifactId(),"issue_proposals","[]","dependency_access_set_id",text(manifest,"access_set_id"),"content_sha256",body.reference().sha256(),"status","READY","revision",1,"updated_at",at));insert("candidate",row);
        insert("lineage_edge",Map.of("tenant_id",h.tenantId(),"consumer_version_id",id,"upstream_version_id",body.artifactId(),"relation_kind","CANDIDATE_BODY","actor_id",a.actorId(),"created_at",at));
        String audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var receipt=json.tree(Map.of("schema_version","1.0.0","candidate_id",id,"run_id",original.runId(),"input_sha256",original.inputSha256(),"body_artifact_id",body.artifactId(),"body_sha256",body.reference().sha256(),"original_evidence_artifact_id",str(evidence,"artifact_id"),"new_evidence_artifact_id",body.artifactId(),"new_evidence_path","/evidence_links","professional_approval",false));
        var auditRow=meta(a,h,at);auditRow.putAll(Map.of("audit_id",audit,"subject_id",a.actorId(),"action","document.candidate.materialized","resource_ref",json.canonical(receipt),"result","SUCCESS","request_id",id,"trace_id",original.runId()));insert("audit_event",auditRow);
        insert("outbox_event",Map.of("tenant_id",h.tenantId(),"event_id",event,"aggregate_id",id,"aggregate_revision",1,"event_type","document.candidate.materialized","payload",json.canonical(receipt),"occurred_at",at));
    }
    public final class Verified {
        private final TaskCandidateAssemblyStageJournal.Original original;private final TaskCandidateAssemblyOriginalReader.Verified physical;private final DocumentReadService.FixedRead base;private final String candidate;private final boolean editable;private JsonNode baseline;
        private Verified(TaskCandidateAssemblyStageJournal.Original original,TaskCandidateAssemblyOriginalReader.Verified physical,DocumentReadService.FixedRead base,String candidate,boolean editable){this.editable=editable;this.original=original;this.physical=physical;this.base=base;this.candidate=candidate;}
        public void requirePermissions(EnterpriseAccess.Admission a)throws Exception{physical.requireUnchanged();permissions(a,header(),candidate,editable);}
        public void requireCurrent(EnterpriseAccess.Admission a)throws Exception{original.requireUnchanged();physical.requireUnchanged();documents.requireCurrent(a,base);requirePermissions(a);var current=inspect(a);if(baseline!=null&&!baseline.equals(current))stale();}
        private JsonNode inspect(EnterpriseAccess.Admission a)throws Exception {
            var h=header();if(editable&&(!h.documentRevision().equals(h.currentDocumentRevision())||!"ACTIVE".equals(h.projectStatus())||"SIGNED".equals(h.status())))stale();
            var row=one(db.queryForList("SELECT * FROM candidate WHERE tenant_id=? AND project_id=? AND candidate_id=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),candidate));if(editable)same("READY",str(row,"status"));same(candidateSha256(),str(row,"content_sha256"));same(physical.artifact("DOCUMENT_BODY").artifactId(),str(row,"content_artifact_id"));same(original.inputSha256(),str(row,"input_sha256"));same(h.documentRevision(),str(row,"base_document_revision"));same(h.snapshotId(),str(row,"snapshot_id"));same(h.planRevision(),str(row,"plan_revision"));same(h.taskRevision(),str(row,"task_revision"));same(h.templateVersion(),str(row,"template_version"));same(original.runId(),str(row,"run_id"));same(original.actionId(),str(row,"action_id"));same("1.0.0",str(row,"schema_version"));same(schemaHash,str(row,"schema_manifest_sha256"));same(json.tree(targetNodes()),json.read(str(row,"target_node_ids")));var version=one(db.queryForList("SELECT content_sha256,entity_kind FROM version_registry WHERE tenant_id=? AND version_id=? LIMIT 2 FOR UPDATE",h.tenantId(),candidate));same(candidateSha256(),str(version,"content_sha256"));same("CANDIDATE",str(version,"entity_kind"));
            var checks=new ArrayList<JsonNode>();for(String id:checkIds()){var check=one(db.queryForList("SELECT * FROM check_run WHERE tenant_id=? AND project_id=? AND check_id=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),id));if(editable&&(check.get("invalidation_reason")!=null||!"SUCCEEDED".equals(str(check,"status"))))stale();checks.add(json.tree(check));}
            var current=documents.authorizeMetadata(a,a.context().context_revision(),h.documentId(),h.documentRevision());if(editable){same(h.documentRevision(),current.header().currentDocumentRevision());same(h.revision(),current.header().revision());}
            return json.tree(Map.of("candidate_id",candidate,"candidate_sha256",candidateSha256(),"input_sha256",original.inputSha256(),"base",json.tree(h),"base_read_sha256",base.digest(),"checks",checks,"auth_epoch",a.context().auth_epoch(),"governance_epoch",a.context().governance_epoch()));
        }
        public InterfaceProtocol.CandidateView view(EnterpriseAccess.Admission a)throws Exception {
            requireCurrent(a);var h=header();var row=one(db.queryForList("SELECT * FROM candidate WHERE tenant_id=? AND project_id=? AND candidate_id=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),candidate));
            var adopted=db.queryForList("SELECT adoption_id,result_document_revision FROM candidate_adoption WHERE tenant_id=? AND project_id=? AND candidate_id=? ORDER BY created_at DESC LIMIT 2",h.tenantId(),h.projectId(),candidate);if(adopted.size()>1)stale();
            var allowed=new ArrayList<String>();if("READY".equals(str(row,"status"))&&h.documentRevision().equals(h.currentDocumentRevision())&&!"SIGNED".equals(h.status())&&resources.find(a,new PermissionProtocol.Scope(h.tenantId(),h.projectId(),"CANDIDATE",candidate),"candidate.adopt","DOCUMENT_BODY").isPresent())allowed.add("candidate.adopt");
            return new InterfaceProtocol.CandidateView(candidate,str(row,"revision"),InterfaceProtocol.CandidateStatus.valueOf(str(row,"status")),h.documentRevision(),targetNodes(),artifactRef(str(row,"content_artifact_id")),artifactRef(str(row,"original_evidence_artifact_id")),artifactRef(str(row,"new_evidence_artifact_id")),checkIds(),original.inputSha256(),h.snapshotId(),h.planRevision(),allowed,adopted.isEmpty()?null:str(adopted.get(0),"adoption_id"),adopted.isEmpty()?null:str(adopted.get(0),"result_document_revision"));
        }
        private CommonProtocol.ArtifactRef artifactRef(String id){var r=one(db.queryForList("SELECT a.sha256,b.schema_ref FROM artifact a JOIN artifact_content_binding b ON b.tenant_id=a.tenant_id AND b.artifact_id=a.artifact_id WHERE a.tenant_id=? AND a.project_id=? AND a.artifact_id=? LIMIT 2 FOR UPDATE",header().tenantId(),header().projectId(),id));String hash=str(r,"sha256");return new CommonProtocol.ArtifactRef(id,hash,str(r,"schema_ref"),new CommonProtocol.Coverage(hash,hash,true,null));}
        public DocumentReadProtocol.Header header(){return base.header();}
        public String candidateId(){return candidate;}
        public String candidateSha256(){return physical.artifact("DOCUMENT_BODY").reference().sha256();}
        public JsonNode body(){return physical.body();}
        public String bodySchemaRef(){return base.bodyIntent().artifact().schemaRef();}
        public String bodySchemaSha256(){return base.bodyIntent().artifact().schemaDocumentSha256();}
        public JsonNode baseBody()throws Exception{return json.read(base.bodyBytes());}
        public JsonNode baseline(){return baseline.deepCopy();}
        public List<String> targetNodes(){return strings(original.input().required("requirement_node_ids"));}
        public List<String> checkIds(){return strings(physical.manifest().required("check_ids"));}
        public List<String> initialRoots()throws Exception{var targets=new LinkedHashSet<>(targetNodes());var byId=new HashMap<String,JsonNode>();baseBody().required("nodes").forEach(n->byId.put(text(n,"node_id"),n));var result=new ArrayList<String>();for(String id:targets){var n=byId.get(id);if(n==null)stale();boolean nested=false;while(!n.required("parent_id").isNull()){String parent=text(n,"parent_id");if(targets.contains(parent)){nested=true;break;}n=byId.get(parent);if(n==null)stale();}if(!nested)result.add(id);}return List.copyOf(result);}
        public void requireInitialBlank(EnterpriseAccess.Admission a)throws Exception{requireCurrent(a);var row=one(db.queryForList("SELECT i.canonical_body,i.body_sha256,r.receipt_json,r.receipt_sha256 FROM document_initial_intent i JOIN document_initial_registration r ON r.tenant_id=i.tenant_id AND r.run_id=i.run_id WHERE i.tenant_id=? AND i.project_id=? AND i.document_id=? AND i.document_revision=? LIMIT 2 FOR UPDATE",header().tenantId(),header().projectId(),header().documentId(),header().documentRevision()));same(header().bodySha256(),str(row,"body_sha256"));same(baseBody(),json.read(str(row,"canonical_body")));same(json.hash(json.read(str(row,"receipt_json"))),str(row,"receipt_sha256"));for(var n:baseBody().required("nodes"))if(!Set.of("DOCUMENT","SECTION").contains(text(n.required("content"),"kind")))stale();}
        public List<ArtifactRegistryProtocol.MemberRow> contentMembers()throws Exception{var members=new TreeMap<String,ArtifactRegistryProtocol.MemberRow>();for(var m:base.dependencies().members())members.put(m.upstreamVersionId(),m);for(var artifact:physical.artifacts())for(var n:artifact.receipt().required("dependency_manifest").required("members")){String id=text(n,"upstream_version_id");String rights=n.required("rights_revision").isNull()?null:text(n,"rights_revision");var member=new ArtifactRegistryProtocol.MemberRow(id,rights);var old=members.putIfAbsent(id,member);if(old!=null&&!old.equals(member))stale();}return List.copyOf(members.values());}
        public List<String> contentRoots()throws Exception{return contentMembers().stream().map(ArtifactRegistryProtocol.MemberRow::upstreamVersionId).toList();}
        public List<String> provenanceRoots(){var roots=new LinkedHashSet<String>();roots.add(header().documentRevision());for(var artifact:physical.artifacts())roots.add(artifact.artifactId());for(var pin:original.input().required("candidates")){roots.add(text(pin,"candidate_artifact_id"));roots.add(text(pin,"body_artifact_id"));}return List.copyOf(roots);}
    }
    private void permissions(EnterpriseAccess.Admission a,DocumentReadProtocol.Header h,String candidate,boolean editable)throws Exception{var scope=new PermissionProtocol.Scope(h.tenantId(),h.projectId(),"DOCUMENT",h.documentId());resources.require(a,scope,"document.read","DOCUMENT_BODY");if(editable)for(String action:List.of("document.write","document.check"))resources.require(a,scope,action,"DOCUMENT_BODY");if(candidate!=null){var c=new PermissionProtocol.Scope(h.tenantId(),h.projectId(),"CANDIDATE",candidate);resources.require(a,c,"candidate.read","DOCUMENT_BODY");if(editable)resources.require(a,c,"candidate.adopt","DOCUMENT_BODY");}}

    private Map<String,Object> meta(EnterpriseAccess.Admission a,DocumentReadProtocol.Header h,java.time.LocalDateTime at)throws Exception{return new LinkedHashMap<>(Map.of("tenant_id",h.tenantId(),"project_id",h.projectId(),"created_by",a.actorId(),"created_at",at,"classification",h.classification(),"schema_version","1.0.0","schema_manifest_sha256",schemaHash));}
    private void insert(String table,Map<String,Object> row){db.update("INSERT INTO "+table+" ("+String.join(",",row.keySet())+") VALUES ("+String.join(",",Collections.nCopies(row.size(),"?"))+")",row.values().toArray());}
    private java.time.LocalDateTime now(){return db.queryForObject("SELECT CURRENT_TIMESTAMP(6)",java.time.LocalDateTime.class);}
    private static List<String> strings(JsonNode n){var out=new ArrayList<String>();n.forEach(v->out.add(v.asText()));return List.copyOf(out);}
    private static Map<String,Object> one(List<Map<String,Object>> rows){if(rows.size()!=1)stale();return rows.get(0);}
    private static String str(Map<String,Object> row,String key){return Objects.requireNonNull(row.get(key)).toString();}
    private static String text(JsonNode n,String key){return n.required(key).asText();}
    private static void same(Object a,Object b){if(!Objects.equals(a,b))stale();}
    private static void stale(){throw new TenantAccessException(ErrorCode.CANDIDATE_STALE);}
}
